alter table public.billing_subscriptions add column event_created bigint not null default 0;
drop function public.record_billing_subscription(text,uuid,text,text,text,text,timestamptz);
create function public.record_billing_subscription(p_event text,p_user uuid,p_customer text,p_subscription text,p_status text,p_price text,p_period timestamptz,p_created bigint) returns boolean language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.billing_customers where user_id=p_user and stripe_customer_id=p_customer) then raise exception 'Customer ownership mismatch'; end if; insert into public.billing_events(event_id) values(p_event) on conflict do nothing; if not found then return false; end if; insert into public.billing_subscriptions(stripe_subscription_id,user_id,stripe_customer_id,status,price_id,current_period_end,event_created) values(p_subscription,p_user,p_customer,p_status,p_price,p_period,p_created) on conflict(stripe_subscription_id) do update set status=excluded.status,price_id=excluded.price_id,current_period_end=excluded.current_period_end,event_created=excluded.event_created,updated_at=now() where public.billing_subscriptions.user_id=excluded.user_id and public.billing_subscriptions.stripe_customer_id=excluded.stripe_customer_id and public.billing_subscriptions.event_created<=excluded.event_created; if not found and not exists(select 1 from public.billing_subscriptions where stripe_subscription_id=p_subscription and user_id=p_user and stripe_customer_id=p_customer) then raise exception 'Subscription ownership mismatch'; end if; return true; end $$;
revoke all on function public.record_billing_subscription(text,uuid,text,text,text,text,timestamptz,bigint) from public;
grant execute on function public.record_billing_subscription(text,uuid,text,text,text,text,timestamptz,bigint) to service_role;
